SELECT p."Registrační číslo projektu",
       GROUP_CONCAT(DISTINCT '; ',  hs."Datum přepnutí" )



FROM projekt p
INNER JOIN historie_stavu hs ON hs.nositelid = p.id
INNER JOIN ciselnik_stav_workflow pwf ON pwf.id = hs.id_stavdo 


WHERE p."Registrační číslo projektu" IN ('CZ.01.01.01/08/25_079/0008312','CZ.01.01.01/08/25_078/0008199','CZ.01.01.01/01/24_063/0006891','CZ.01.01.01/01/24_063/0006676','CZ.01.01.01/01/24_056/0007984','CZ.01.01.01/01/24_056/0006544','CZ.01.01.01/01/24_063/0006924','CZ.01.01.01/01/24_063/0006853','CZ.01.05.01/01/23_029/0004697','CZ.01.05.02/01/23_028/0004033','CZ.01.01.01/03/24_061/0007650','CZ.01.01.01/07/24_046/0007005','CZ.01.01.01/07/24_046/0007272','CZ.01.04.01/01/24_049/0007461','CZ.01.04.01/01/24_049/0007451','CZ.01.04.01/01/24_049/0007449','CZ.01.04.01/01/24_049/0007408','CZ.01.04.01/01/24_049/0007385','CZ.01.04.01/01/24_049/0007006','CZ.01.04.01/01/24_049/0006229','CZ.01.04.01/01/24_049/0005878','CZ.01.04.03/01/23_032/0005092','CZ.01.02.01/05/24_059/0006383','CZ.01.02.01/05/24_059/0006402','CZ.01.01.01/01/24_063/0006867','CZ.01.01.01/01/24_063/0006924','CZ.01.01.01/01/24_063/0006867','CZ.01.01.01/01/24_063/0006867','CZ.01.01.01/01/24_063/0006908')


AND pwf."Kód" = 'PP25b'

GROUP BY p."Registrační číslo projektu" 
